function productDefaults(){defaults({profiles:{工作日:null,周末:null},profile:'周末',remaining:0,deadline:null,sessions:[]})}
function productRender(){put(`<div class="grid"><div>${box('今天的专注计时',`<div class="time-display" id="session-clock"></div><div class="row">${btn('开始本次使用','start-clock')}${btn('暂停','pause-clock','')}${btn('结束并记录','end-clock','')}</div>${note('这是页面内计时器，不能锁住设备。后台休眠可能推迟提示；恢复页面时按真实时间重新计算。')}`)}${box('本次与历史使用',rows(p.sessions.slice().reverse(),x=>`<div class="item"><span>${x.date}</span><b>${x.minutes} 分钟</b></div>`))}</div><div>${box('工作日与周末分别协商',`<form id="profile" class="stack">${select('保存为哪套约定','profile',['工作日','周末'],p.profile)}<button>把当前共同约定保存到此方案</button></form><div class="row" style="margin-top:15px">${Object.keys(p.profiles).map(k=>`<button data-load="${k}" ${p.profiles[k]?'':'disabled'}>载入${k}</button>`).join('')}</div>`)}${box('约定执行回顾',`<p>已记录 ${state.reviews.length} 次复盘。</p><p>在当时约定内：${state.reviews.filter(x=>x.actual<=x.allowed).length} 次</p><p>需要重新讨论：${state.reviews.filter(x=>x.actual>x.allowed).length} 次</p><p>计时不自动评判好坏；结束后一起填写上方复盘。</p>`,'tint')}</div></div>`);on('start-clock',()=>{if(p.deadline)return toast('计时正在运行');if(p.remaining<=0){p.remaining=allowance()*60;p.startedAt=Date.now();p.initial=p.remaining}if(!p.remaining)return toast('请先共同设置大于零的允许时长');p.deadline=Date.now()+p.remaining*1000;commit()});on('pause-clock',()=>{if(!p.deadline)return;p.remaining=Math.max(0,Math.ceil((p.deadline-Date.now())/1000));p.deadline=null;commit()});on('end-clock',()=>{if(!p.initial)return toast('请先开始一次计时');const remain=p.deadline?Math.max(0,Math.ceil((p.deadline-Date.now())/1000)):p.remaining;p.sessions.push({date:today(),minutes:Math.round((p.initial-remain)/60)});p.deadline=null;p.remaining=0;p.initial=0;commit()});form('profile',v=>{p.profile=v.profile;p.profiles[v.profile]=clone(state.agreement);commit()});deleteButtons('load',name=>{state.agreement=clone(p.profiles[name]);p.profile=name;commit()});tickClock()}
function tickClock(){if(!p||!$('#session-clock'))return;const remain=p.deadline?Math.max(0,Math.ceil((p.deadline-Date.now())/1000)):p.remaining;$('#session-clock').textContent=humanTime(remain);if(p.deadline&&remain===0){p.deadline=null;p.remaining=0;save();toast('约定时长到了，先暂停并一起复盘')}}setInterval(tickClock,1000);
